class SelfHealingMeshController:
    def __init__(self):
        self.services = {}  # {service_id: ServiceState}
        self.circuit_breaker_threshold = 3
        self.failure_window = 2  # seconds
        self.backoff_multipliers = [1, 2, 4, 8]  # seconds

    def monitor(self):
        while True:
            for service_id, state in self.services.items():
                if self.detect_failure(service_id):
                    self.handle_failure(service_id)

    def detect_failure(self, service_id):
        # Check if service failed within last 2 seconds
        recent_failures = [
            f for f in self.services[service_id].failures
            if time.time() - f.timestamp < self.failure_window
        ]
        return len(recent_failures) >= self.circuit_breaker_threshold

    def handle_failure(self, service_id):
        service = self.services[service_id]

        if service.restart_attempts < len(self.backoff_multipliers):
            delay = self.backoff_multipliers[service.restart_attempts]
            schedule_restart(service_id, delay)
            service.restart_attempts += 1
        else:
            spawn_stub(service_id)
            service.status = "STUB"

    def spawn_stub(self, service_id):
        # Create lightweight stub service
        stub = create_stub(service_id)
        self.services[service_id] = stub
```

The controller continuously monitors services, triggers restarts with exponential backoff after 2s failure detection, and spawns stubs after 3 consecutive failures.
